input.proposed_solution:
Lowercase only the domain (after the last '@'), keep the local part exactly as typed, keep trimming. Strings without a usable '@' are returned trimmed. Added tests for domain-only lowercasing, quoted local parts containing '@', and input without a domain.

Patch (already applied in the repository snapshot):
```diff
--- a/src/email.js
+++ b/src/email.js
@@ -2,8 +2,12 @@

 /**
  * Normalize an e-mail address for storage and uniqueness checks.
+ * The domain is case-insensitive (RFC 5321 §2.4); the local part is preserved as typed.
  * @param {string} email
  */
 export function normalizeEmail(email) {
-  return email.trim();
+  const trimmed = email.trim();
+  const at = trimmed.lastIndexOf("@");
+  if (at <= 0) return trimmed;
+  return trimmed.slice(0, at) + "@" + trimmed.slice(at + 1).toLowerCase();
 }
--- a/test/email.test.js
+++ b/test/email.test.js
@@ -3,3 +3,7 @@
 import { normalizeEmail } from "../src/email.js";

 test("trims whitespace", () => assert.equal(normalizeEmail("  a@example.com "), "a@example.com"));
+
+test("lowercases the domain only", () => assert.equal(normalizeEmail("John.Doe@Example.COM"), "John.Doe@example.com"));
+test("uses the last @ (quoted local parts)", () => assert.equal(normalizeEmail('"a@b"@EXAMPLE.com'), '"a@b"@example.com'));
+test("leaves strings without a domain alone", () => assert.equal(normalizeEmail(" nodomain "), "nodomain"));
```
